import type { BusinessRecord, CategoryId, Image } from "./types.ts";

/**
 * The scene library (Oct 2026): public-domain (CC0 / public domain mark) photos of each trade, so a business with no
 * photo of its own still gets a photo-led page instead of a flat color block. They are atmosphere, never "our work":
 * no people's faces, no children, no logos, nothing that claims to be this business. Files live in
 * app/public/scenes/<file> (1600 px wide JPEGs); previews serve them from the app, publishing copies the ones a page uses.
 * The owner's own photos always win; Google photos show in previews only and a scene takes their place when publishing.
 */
export interface Scene {
  file: string;
  cats: CategoryId[];
  /** Narrower fits (a pack variant or a word in the business type), tried before the category's general scenes. */
  fits?: string[];
  alt: string;
  w: number;
  h: number;
  /** Where it came from (CC0 needs no credit; kept for our records). */
  source: string;
}

